// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address caller, address owner, address operator) public {
        vm.assume(owner != operator);
        vm.assume(caller != address(0));
        vm.assume(owner != address(0));
        vm.assume(operator != address(0));

        vm.prank(owner);
        c.setApprovalForAll(operator, true);

        bool result = c.isApprovedForAll(owner, operator);

        assertTrue(result);
    }
}
